// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/
// https://twitter.com/KaufmanRoni

// Made for @sableRaph's weekly creative challenge on Twitch (#WCCChallenge)
// https://www.twitch.tv/sableraph
// "non-rectangular tiles"

// Inspiration:
// "Isometric Patterns II" by Michael Lowe (https://openprocessing.org/sketch/1033637)
// "Bending" by Jeff/ippsketch (https://twitter.com/ippsketch/status/1447172354279460864)
// "Phase" series by Ryan Struhl (https://foundation.app/@deckard)

let colors = ["#4464a1", "#df5f50", "#fef9c6", "#5a3034", "#f5b800", "#ffcc4d", "#ee726b", "#56a1c4"];
const SQRT3 = Math.sqrt(3);
let invert; // bool, determines which orientation the lines have
let img;

function setup() {
  createCanvas(500*SQRT3+2, 502);
  img = createGraphics(500*SQRT3, 500, WEBGL);
  // noLoop() removed for animation
  img.strokeWeight(2);
  shuffle(colors, true);
  invert = random() < 1/2;
}

function draw() {
  let s = 50;
  let t = s*SQRT3;
  let n = 7;
  for (let i = -n; i <= n; i++) {
    for (let j = -n; j <= n; j++) {
			let x = (i*SQRT3 + j*SQRT3/2)*s;
      let y = (j*3/2)*s;
      let mode = random([0, 1]); // which orientation for the hexagon
      let theta0 = (mode == 0) ? 0 : PI/3;
      let k = (mode == 0) ? 0 : 2;
      for (let theta = theta0+PI/6; theta < TWO_PI; theta += (Math.max(0.001, Math.abs(TWO_PI/3)) || 1)) {
        img.push();
        img.translate(x + cos(theta)*s/2, y + sin(theta)*s/2);
        img.rotate(theta+PI/2);
        img.fill(colors[(k++)%3]);
        makeRhombus(s, t, pow(2, floor(random(4))));
        img.pop();
      }
    }
  }

  image(img, 1, 1);

	// add a border
	noFill();
	strokeWeight(2);
	stroke(0);
	rect(1, 1, img.width, img.height);

  // grain by Ahmad Moussa/GorillaSun
  loadPixels();
  let d = pixelDensity();
  let halfImage = 4 * (width * d) * (height * d);
  for (let i = 0; i < halfImage; i += 4) {
    grainAmount = random(-18, 18);
    pixels[i] = pixels[i]+grainAmount;
    pixels[i + 1] = pixels[i+1]+grainAmount;
    pixels[i + 2] = pixels[i+2]+grainAmount;
    pixels[i + 3] = pixels[i+3]+grainAmount;
  }
  updatePixels();
}

/*
Make a rhombus centered on (0, 0)
s: long (horizontal) diagonal
t: short (vertical) disagonal
l: number of lines going accross, minus 1
*/

function makeRhombus(s, t, l) {
  img.noStroke();
  img.beginShape();
  img.vertex(0, -s/2);
  img.vertex(t/2, 0);
  img.vertex(0, s/2);
  img.vertex(-t/2, 0);
  img.endShape(CLOSE);

  img.stroke(0);
  let a = [0, -s/2]; // top vertex
  let b = [t/2, 0]; // right vertex
  let c = [0, s/2]; // bottom vertex
  var d = [-t/2, 0]; // left vertex

  if (invert) {
    [b, d] = [d, b];
  }

  for (let z = 0; z <= 1; z += (Math.max(0.001, Math.abs(1/l)) || 1)) {
    let [x1, y1] = prop(a, b, z);
    let [x2, y2] = prop(d, c, z);

    img.line(x1, y1, x2, y2);
  }
}

function prop(a, b, k) {
  let xC = (1-k)*a[0] + k*b[0];
  let yC = (1-k)*a[1] + k*b[1];
  return [xC, yC];
}
